function treeDepth(root: TreeNode | null): number {
  let row: TreeNode[] = root ? [root] : [];
  let levels = 0;
  while (row.length) {
    const next: TreeNode[] = [];
    for (const node of row) {
      if (node.left) next.push(node.left);
      if (node.right) next.push(node.right);
    }
    row = next;
    levels++;
  }
  return levels;
}

