class Solution:
    def treeDepth(self, root: Optional[TreeNode]) -> int:
        queue = deque([root] if root else [])
        levels = 0
        while queue:
            for _ in range(len(queue)):  # exactly one row
                node = queue.popleft()
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            levels += 1
        return levels

